T=np.load('T.npy'); C=np.load('C.npy'); d=np.load('dec2.npz'); np.set_printoptions(linewidth=250,suppress=True,precision=2)
def refine0(t,c,F,G):
    M=c>=np.quantile(c,.3)
    F2=F.copy(); G2=G.copy()
    for i in range(32):
        v=[]
        for j in range(32):
            if M[i,j] and t[i,j]<7 and abs(F[i]-G[j])>=1:
                v.append(G[j]+np.sign(F[i]-G[j])*(t[i,j]+.5))
        if v: F2[i]=np.mean(v)
    for j in range(32):
        v=[]
        for i in range(32):
            if M[i,j] and t[i,j]<7 and abs(F2[i]-G[j])>=1:
                v.append(F2[i]-np.sign(F2[i]-G[j])*(t[i,j]+.5))
        if v: G2[j]=np.mean(v)
