def refine1(t,c,F,G):
    M=(c>=np.quantile(c,.3))&(t>0)&(t<7)
    F2=np.array([np.mean((t[i]+.5-G)[M[i]]) if M[i].any() else F[i] for i in range(32)])
    G2=np.array([np.mean((t[:,j]+.5-F2)[M[:,j]]) if M[:,j].any() else G[j] for j in range(32)])
